// Auto-generated standard Wordle word lists.
// Curated target solutions (2315 words) and allowed guesses (10657 words).

export const TARGET_BLOB =
  "";

export const ALLOWED_BLOB =
  "";

export const TARGET_WORDS: readonly string[] = (() => {
  const list: string[] = [];
  for (let i = 0; i < TARGET_BLOB.length; i += 5) {
    list.push(TARGET_BLOB.slice(i, i + 5));
  }
  return Object.freeze(list);
})();

function binarySearch5(target: string, blob: string): boolean {
  let low = 0;
  let high = blob.length / 5 - 1;
  while (low <= high) {
    const mid = (low + high) >> 1;
    const idx = mid * 5;
    const word = blob.slice(idx, idx + 5);
    if (word === target) return true;
    if (word < target) low = mid + 1;
    else high = mid - 1;
  }
  return false;
}

/** Checks if a 5-letter word is a valid guess (either in targets or allowed guesses). */
export function isValidWord(raw: string): boolean {
  if (!raw || raw.length !== 5) return false;
  const word = raw.toUpperCase();
  return binarySearch5(word, TARGET_BLOB) || binarySearch5(word, ALLOWED_BLOB);
}

/** Reference epoch for daily puzzles: Jan 1, 2024 */
const DAILY_EPOCH = new Date(2024, 0, 1).getTime();
const MS_PER_DAY = 86_400_000;

/** Computes the day index and target word for a given date. */
export function getDailyWord(date: Date = new Date()): { word: string; puzzleNumber: number; dateString: string } {
  // Use local calendar date to determine day number
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  const dateString = `${y}-${m}-${d}`;

  // Start of day in local time relative to epoch
  const localDayStart = new Date(y, date.getMonth(), date.getDate()).getTime();
  const daysSinceEpoch = Math.floor((localDayStart - DAILY_EPOCH) / MS_PER_DAY);
  const puzzleNumber = Math.max(1, daysSinceEpoch);

  // Deterministic pseudo-random shuffle index so words don't appear in alphabetical order!
  // Linear congruential generator step mapped to target length
  const index = ((puzzleNumber * 1103515245 + 12345) >>> 0) % TARGET_WORDS.length;
  const word = TARGET_WORDS[index];

  return { word, puzzleNumber, dateString };
}

/** Picks a random word from the curated target answers. */
export function getRandomWord(): string {
  const idx = Math.floor(Math.random() * TARGET_WORDS.length);
  return TARGET_WORDS[idx];
}
